css:
.uv-rdd {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-rdd {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: flex;
  flex-direction: column;
  gap: .9em;
}

.uv-rdd label {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: inline-flex;
  align-items: center;
  gap: .7em;
  cursor: pointer;
  user-select: none;
  font-weight: 500;
}

.uv-rdd input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

.uv-rdd .rb {
  display: grid;
  place-items: center;
  width: 1.4em;
  height: 1.4em;
  border-radius: 50%;
  box-shadow: inset 0 0 0 2px color-mix(in srgb,var(--fg) 22%,transparent);
  transition: box-shadow calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-rdd i {
  width: .68em;
  height: .68em;
  border-radius: 50%;
  background: var(--c1);
  scale: 0;
  transition: scale calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-rdd label:hover .rb {
  box-shadow: inset 0 0 0 2px var(--c1);
}

.uv-rdd input:checked + .rb {
  box-shadow: inset 0 0 0 2px var(--c1);
}

.uv-rdd input:checked + .rb i {
  scale: 1;
}

