  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq04-cam {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
}

.uvq04-cam legend {
  padding: 0;
  margin: 0 0 .8em;
  font-weight: 700;
}

.uvq04-cam .ph {
  width: 18em;
  padding: .55em .55em .9em;
  border-radius: 1.6em;
  background: #0b0b0c;
  box-shadow: 0 1.2em 2.4em -1.2em rgba(0,0,0,.6),0 0 0 1px rgba(255,255,255,.06);
}

.uvq04-cam .vf {
  position: relative;
  height: 9.5em;
  border-radius: 1.1em;
