}

.uvq04-cam .vf i,.uvq04-cam .bd {
  position: absolute;
  transition: opacity calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq04-cam .bk {
  inset: 0;
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  -webkit-mask: radial-gradient(closest-side,transparent 55%,#000);
  mask: radial-gradient(closest-side,transparent 55%,#000);
  opacity: 0;
}

.uvq04-cam .gr {
  inset: 0;
  background: linear-gradient(90deg,transparent calc(33.3% - .5px),rgba(255,255,255,.4) 0 calc(33.3% + .5px),transparent 0 calc(66.6% - .5px),rgba(255,255,255,.4) 0 calc(66.6% + .5px),transparent 0),linear-gradient(transparent calc(33.3% - .5px),rgba(255,255,255,.4) 0 calc(33.3% + .5px),transparent 0 calc(66.6% - .5px),rgba(255,255,255,.4) 0 calc(66.6% + .5px),transparent 0);
}

.uvq04-cam .fc {
  left: 50%;
  top: 50%;
  width: 2.4em;
  height: 2.4em;
  margin: -1.2em;
  border: 1px solid var(--c1);
  animation: uvq04-cam-fc calc(2.4s / var(--k)) cubic-bezier(.25,.1,.25,1) infinite;
}

.uvq04-cam .pa {
  left: 12%;
  right: 12%;
  top: 50%;
  height: 2px;
  margin-top: -1px;
  background: rgba(255,255,255,.85);
  opacity: 0;
}

.uvq04-cam .pa::after {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  width: 1.3em;
  height: 1.3em;
