  font-variant-numeric: tabular-nums;
  color: #fff;
  background: rgba(0,0,0,.45);
}

.uvq04-cam .bd::after {
  content: var(--b,"4:3");
}

.uvq04-cam .md {
  position: relative;
  height: 2.3em;
  margin-top: .6em;
  overflow: hidden;
  -webkit-mask: linear-gradient(90deg,transparent,#000 22%,#000 78%,transparent);
