}

.uvq04-cam label:hover span {
  color: #fff;
}

.uvq04-cam input:checked + span {
  color: var(--c1);
}

.uvq04-cam input:focus-visible + span {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
  outline-offset: 0;
}

.uvq04-cam .sh {
  display: grid;
  place-items: center;
  width: 3.3em;
  height: 3.3em;
  margin: .35em auto 0;
  border-radius: 50%;
  box-shadow: inset 0 0 0 .2em #fff;
}

.uvq04-cam .sh i {
  width: 2.5em;
  height: 2.5em;
  border-radius: 50%;
  background: #fff;
  transition: background calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq04-cam .sh:active i {
  transform: scale(.88);
}

.uvq04-cam:has(label:nth-of-type(1) input:checked) .tr {
  --i: 0;
}

.uvq04-cam:has(label:nth-of-type(1) input:checked) .bd {
  --b: "120 FPS";
  background: var(--c2);
}

.uvq04-cam:has(label:nth-of-type(1) input:checked) .sh i {
  background: var(--c2);
  transform: scale(.86);
}

.uvq04-cam:has(label:nth-of-type(1) input:checked) .fc {
  opacity: 0;
}

.uvq04-cam:has(label:nth-of-type(2) input:checked) .tr {
  --i: 1;
}

.uvq04-cam:has(label:nth-of-type(2) input:checked) .bd {
  --b: "00:00";
  background: var(--c2);
}

.uvq04-cam:has(label:nth-of-type(2) input:checked) .sh i {
  background: var(--c2);
  transform: scale(.86);
}

.uvq04-cam:has(label:nth-of-type(2) input:checked) .fc {
  opacity: 0;
}

.uvq04-cam:has(label:nth-of-type(3) input:checked) .tr {
  --i: 2;
}

.uvq04-cam:has(label:nth-of-type(3) input:checked) .bd {
  --b: "4:3";
}

.uvq04-cam:has(label:nth-of-type(4) input:checked) .tr {
  --i: 3;
}

.uvq04-cam:has(label:nth-of-type(4) input:checked) .bd {
  --b: "f/1.8";
}

.uvq04-cam:has(label:nth-of-type(5) input:checked) .tr {
  --i: 4;
}

.uvq04-cam:has(label:nth-of-type(5) input:checked) .bd {
  --b: "180°";
}

.uvq04-cam:has(label:nth-of-type(4) input:checked) .bk {
  opacity: 1;
}

.uvq04-cam:has(label:nth-of-type(5) input:checked) .pa {
  opacity: 1;
}

.uvq04-cam:has(label:nth-of-type(5) input:checked) .gr,.uvq04-cam:has(label:nth-of-type(5) input:checked) .fc {
  opacity: 0;
}

@keyframes uvq04-cam-fc {
  0%,100% {
    transform: scale(1);
  }
  50% {
    transform: scale(.9);
  }
}

@keyframes uvq04-cam-pa {
  to {
    left: calc(100% - 1.3em);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq04-cam,.uvq04-cam *,.uvq04-cam *::before,.uvq04-cam *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

