}

.uvq04-pst .nm {
  font-size: .55em;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
  white-space: nowrap;
  color: #2d2f33;
}

.uvq04-pst label:hover .ky {
  transform: translateY(.08em);
}

.uvq04-pst label:active .ky {
  transform: translateY(.3em);
  box-shadow: 0 .12em 0 color-mix(in srgb,var(--c2),#000 40%),0 .2em .3em rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.6);
}

.uvq04-pst input:checked + .ky {
  transform: translateY(.36em);
  background: linear-gradient(var(--c2),color-mix(in srgb,var(--c2),#000 10%));
