}

.uvq04-pst input:checked ~ .nm {
  color: color-mix(in srgb,var(--c1),#000 35%);
}

.uvq04-pst input:focus-visible + .ky {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq04-pst:has(label:nth-of-type(1) input:checked) .fq {
  --f: "89.6";
}

.uvq04-pst:has(label:nth-of-type(2) input:checked) .fq {
  --f: "94.0";
}

.uvq04-pst:has(label:nth-of-type(3) input:checked) .fq {
  --f: "98.3";
}

.uvq04-pst:has(label:nth-of-type(4) input:checked) .fq {
  --f: "102.7";
}

.uvq04-pst:has(label:nth-of-type(5) input:checked) .fq {
  --f: "106.1";
}

@media (prefers-reduced-motion:reduce) {
  .uvq04-pst,.uvq04-pst *,.uvq04-pst *::before,.uvq04-pst *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

