css:
.uvq04-spl {
  --c1: #c9965c;
  --c2: #7a5230;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq04-spl {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
  text-align: center;
}

.uvq04-spl legend {
  padding: 0;
  margin: 0 0 .8em;
  font-weight: 700;
  width: 100%;
}

.uvq04-spl .rw {
  display: flex;
  justify-content: center;
  gap: .5em;
  padding: 0 .5em;
  background: linear-gradient(color-mix(in srgb,var(--c2),#fff 15%),color-mix(in srgb,var(--c2),#000 25%)) 0 3.35em/100% .32em no-repeat;
}

.uvq04-spl label {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 3.3em;
  cursor: pointer;
}

.uvq04-spl input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uvq04-spl .sp {
  position: relative;
  display: block;
  width: 2.3em;
  height: 3.35em;
  transition: transform calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq04-spl .sp::before,.uvq04-spl .sp::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  height: .5em;
  border-radius: .25em;
  background: linear-gradient(90deg,color-mix(in srgb,var(--c1),#000 32%),var(--c1) 35%,color-mix(in srgb,var(--c1),#fff 32%) 50%,var(--c1) 65%,color-mix(in srgb,var(--c1),#000 38%));
  box-shadow: 0 .1em .15em rgba(0,0,0,.28);
}

.uvq04-spl .sp::before {
  top: 0;
}

.uvq04-spl .sp::after {
  bottom: 0;
}

.uvq04-spl .bd {
  position: absolute;
  left: .28em;
  right: .28em;
  top: .42em;
  bottom: .42em;
  background: repeating-linear-gradient(rgba(0,0,0,.17) 0 1px,transparent 1px 3px) 0 0/100% 3px,linear-gradient(90deg,color-mix(in srgb,var(--c),#000 38%),var(--c) 30%,color-mix(in srgb,var(--c),#fff 30%) 48%,var(--c) 66%,color-mix(in srgb,var(--c),#000 42%));
}

.uvq04-spl .th {
  display: block;
  width: 1.4em;
  height: 2.3em;
  margin-top: -.15em;
  overflow: visible;
}

.uvq04-spl .th path {
  fill: none;
  stroke: var(--c);
  stroke-width: 1.6;
  stroke-linecap: round;
  filter: drop-shadow(0 0 .4px rgba(0,0,0,.45));
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  transition: stroke-dashoffset calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq04-spl .nm {
  font-size: .66em;
  font-weight: 600;
  line-height: 1.15;
  overflow-wrap: anywhere;
  hyphens: auto;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  transition: color calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq04-spl label:hover .sp {
  transform: translateY(-.12em) rotate(-4deg);
}

.uvq04-spl label:active .sp {
  transform: scale(.93);
}

.uvq04-spl input:checked + .sp {
  transform: translateY(-.35em);
}

.uvq04-spl input:checked + .sp .bd {
  animation: uvq04-spl calc(0.3s / var(--k)) linear infinite;
}

.uvq04-spl input:checked ~ .th path {
  stroke-dashoffset: 0;
  transition: stroke-dashoffset calc(0.9s / var(--k)) cubic-bezier(.22,1,.36,1) calc(0.15s / var(--k));
}

.uvq04-spl input:checked ~ .nm {
  color: var(--fg);
  font-weight: 800;
}

.uvq04-spl input:focus-visible + .sp {
  outline: 2px solid var(--fg);
  outline-offset: 3px;
  border-radius: .3em;
}

@keyframes uvq04-spl {
  to {
    background-position: 0 -3px,0 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq04-spl,.uvq04-spl *,.uvq04-spl *::before,.uvq04-spl *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

