.uvq04-tee:has(label:nth-of-type(4) input:checked) .sh {
  fill: url(#uvq04-tee-tt);
}

.uvq04-tee:has(label:nth-of-type(4) input:checked) .pv svg {
  animation: uvq04-tee4 calc(0.55s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

