.uvq04-care {
  --c1: #1f5f8b;
  --c2: #8f96a0;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq04-care {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.uvq04-care legend {
  padding: 0;
  margin: 0 0 .8em;
  font-weight: 700;
  width: 100%;
  text-align: center;
}

.uvq04-care .sm {
  position: relative;
  z-index: 1;
  width: 15em;
  height: 1.3em;
  border-radius: .3em;
  background: repeating-linear-gradient(90deg,rgba(0,0,0,.12) 0 1px,transparent 1px 3px),linear-gradient(color-mix(in srgb,var(--c2),#fff 15%),color-mix(in srgb,var(--c2),#000 15%));
  box-shadow: 0 .2em .35em rgba(0,0,0,.25);
}

.uvq04-care .sm::after {
  content: "";
  position: absolute;
  left: .4em;
  right: .4em;
  top: 50%;
  border-top: 1.5px dashed rgba(255,255,255,.55);
}

.uvq04-care .lb {
  width: 11.5em;
  margin-top: -.45em;
  padding: 1.3em .8em 1em;
  box-sizing: border-box;
  border-radius: 0 0 .2em .2em;
  color: #3a3a3a;
  background: linear-gradient(100deg,transparent 18%,rgba(255,255,255,.65) 34%,transparent 50%),repeating-linear-gradient(90deg,rgba(0,0,0,.025) 0 1px,transparent 1px 2px),#f6f4ef;
  box-shadow: 0 .8em 1.6em -1em rgba(0,0,0,.5),inset 0 .5em .4em -.4em rgba(0,0,0,.18);
}

.uvq04-care .cm {
  margin: 0 0 .7em;
  text-align: center;
  font-size: .64em;
  font-weight: 700;
  letter-spacing: .06em;
  line-height: 1.5;
  text-transform: uppercase;
}

.uvq04-care label {
  position: relative;
  display: grid;
  grid-template-columns: 1.9em 1fr;
  align-items: center;
  gap: .6em;
  margin-bottom: .25em;
  padding: .3em .45em;
  border: 1.5px dashed transparent;
  border-radius: .4em;
  cursor: pointer;
  transition: background calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),border-color calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq04-care input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uvq04-care label svg {
  width: 1.9em;
  height: 1.9em;
  fill: none;
  stroke: #3a3a3a;
  stroke-width: 1.4;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: stroke calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq04-care label svg .f {
  fill: #3a3a3a;
  stroke: none;
  transition: fill calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq04-care label span {
  display: flex;
  flex-direction: column;
  line-height: 1.25;
}

.uvq04-care label b {
  font-size: .82em;
}

.uvq04-care label small {
  font-size: .66em;
  opacity: .65;
}

.uvq04-care label:hover {
  background: rgba(0,0,0,.04);
}

.uvq04-care label:active {
  transform: scale(.98);
}

.uvq04-care label:has(input:checked) {
  border-color: var(--c1);
  background: color-mix(in srgb,var(--c1) 9%,transparent);
  color: var(--c1);
}

.uvq04-care input:checked + svg {
  stroke: var(--c1);
  animation: uvq04-care calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq04-care input:checked + svg .f {
  fill: var(--c1);
}

.uvq04-care label:has(input:focus-visible) {
  outline: 2px solid #3a3a3a;
  outline-offset: 2px;
}

.uvq04-care .mk {
  margin: .6em 0 0;
  text-align: center;
  font-size: .56em;
  letter-spacing: .16em;
  text-transform: uppercase;
  opacity: .55;
}

@keyframes uvq04-care {
  from {
    transform: scale(.7);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq04-care,.uvq04-care *,.uvq04-care *::before,.uvq04-care *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

